import 'package:flutter/material.dart';
import 'specialty_section_header.dart';
class DoctorsSection extends StatelessWidget { final String title; final Color accentColor; final List<Widget> doctors; final VoidCallback? onSeeAll; const DoctorsSection({super.key,this.title='الأطباء',required this.accentColor,required this.doctors,this.onSeeAll}); @override Widget build(BuildContext context){return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[SpecialtySectionHeader(title:title,accentColor:accentColor,onSeeAll:onSeeAll),const SizedBox(height:10),if(doctors.isEmpty)const Padding(padding:EdgeInsets.all(12),child:Text('لا توجد بيانات متاحة حالياً'))else SizedBox(height:190,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:doctors.length,separatorBuilder:(_,__)=>const SizedBox(width:10),itemBuilder:(_,i)=>SizedBox(width:165,child:doctors[i])))]);}}
